/**
 * The showcase generated by `pdx build --ssg` (#160), for `ssg-pages.spec.ts`: a `globalSetup` of
 * `playwright.timing.config.ts`, beside the client build that config already serves, so the two are
 * measured on the same machine with nothing else running.
 *
 * Generated from the CLI's sources, as the scenario suite's generated app is (`scenarios-build.ts`):
 * the showcase does not depend on the CLI's package. With the app's own `pdx.config.ts` — every route,
 * a path for each one with parameters, and the build session (`src/ssg.ts`) — and its SSG Vite config,
 * into `dist-ssg/`. Then served by Vite's preview, which brings the mock server the app signs in
 * against and fetches from, and which answers `/tickets` with `tickets/index.html`.
 *
 * What the build reported is written beside the session, for the spec to hold.
 */
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { preview } from 'vite';
import { signIn } from './session';

const packageDir = resolve(dirname(fileURLToPath(import.meta.url)), '..');

/** The port the generated site is served on: the timing config's client build is on 5314. */
export const SSG_PORT = 5315;
export const SSG_URL = `http://localhost:${SSG_PORT}`;
/** What `buildSsg` reported. */
export const SSG_REPORT = join(packageDir, 'test-results', '.ssg', 'report.json');
const SSG_DIST = join(packageDir, 'dist-ssg');
const SSG_CONFIG = join(packageDir, 'vite.ssg.config.ts');

export default async function generateSite(): Promise<() => Promise<void>> {
    const { buildSsg } = await import('../../cli/src/commands/build-ssg');
    const { loadConfig, resolveConfig } = await import('../../cli/src/config/loader');
    // A stale page from an earlier build would be opened as if this one had written it.
    rmSync(SSG_DIST, { recursive: true, force: true });
    const report = await buildSsg(packageDir, resolveConfig(await loadConfig(packageDir), packageDir), SSG_DIST, false, SSG_CONFIG);
    mkdirSync(dirname(SSG_REPORT), { recursive: true });
    writeFileSync(SSG_REPORT, JSON.stringify(report, null, 2));

    const server = await preview({ root: packageDir, configFile: SSG_CONFIG, logLevel: 'warn', preview: { port: SSG_PORT, strictPort: true } });
    await signIn(SSG_URL);
    return async () => { await new Promise<void>((done) => server.httpServer.close(() => done())); };
}
